import{_ as s,a0 as r,w as l,s as p,ao as u,I as a,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Linux有問必答：如何檢查Linux系統的最後重啓時間 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何檢查Linux系統的最後重啓時間 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何檢查Linux系統的最後重啓時間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何檢查Linux系統的最後重啓時間 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140811 Linux FAQs with Answers--How to check the last time system was rebooted on Linux","title":"Linux有問必答：如何檢查Linux系統的最後重啓時間","tag":"201409","desc":""},"relativePath":"201409/20140811 Linux FAQs with Answers--How to check the last time system was rebooted on Linux.md","filePath":"[post].md"}'),m={name:"201409/20140811 Linux FAQs with Answers--How to check the last time system was rebooted on Linux.md"};function d(x,t,h,L,f,_){const o=r("Link");return l(),p("div",null,[t[11]||(t[11]=u(`<h1 id="linux有問必答-如何檢查linux系統的最後重啓時間" tabindex="-1">Linux有問必答：如何檢查Linux系統的最後重啓時間 <a class="header-anchor" href="#linux有問必答-如何檢查linux系統的最後重啓時間" aria-label="Permalink to “Linux有問必答：如何檢查Linux系統的最後重啓時間”">​</a></h1><blockquote><p><strong>問題</strong>: 是否有一個命令可以快速地檢查系統已經運行了多久? 也就是我怎麼知道Linux系統最後的重啓時間?</p></blockquote><p>有許多方法來查詢系統最後的重啓時間。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>第一種方法是使用last命令</p><pre><code>$ last reboot 
</code></pre><p><img src="https://farm4.staticflickr.com/3925/14881994335_041e9c2f86_z.jpg" alt=""></p><p>這條命令實際上顯示的是最近幾天的系統運行時間。last原本被設計來顯示某個特定用户的登錄歷史。在Linux中，有一個特別的“偽用户”稱為reboot會在系統重啓的時候立即自動登錄。這樣通過檢查reboot用户的登錄歷史，你就可以檢查最後的重啓時間。</p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>另外一個檢測系統最後啓動時間的方法是使用who命令帶上‘-b’選項。</p><pre><code>$ who -b 
</code></pre><h3 id="方法三" tabindex="-1">方法三 <a class="header-anchor" href="#方法三" aria-label="Permalink to “方法三”">​</a></h3><p>你同樣可以使用uptime命令來推斷系統最後的啓動時間。uptime命令會顯示當前的時間，同樣也會顯示系統已經運行的時間。從這些信息中，你就可以計算系統最後啓動的時間了</p><pre><code>$ uptime 
</code></pre><p><img src="https://farm4.staticflickr.com/3915/14881660192_58f2843969_o.png" alt=""></p><hr>`,16)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(o,{href:"http://ask.xmodulo.com/check-last-time-system-rebooted-linux.html"},{default:n(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/check-last-time-system-rebooted-linux.html",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=e("譯者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[2]||(t[2]=[e("geekpi",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),i(o,{href:"https://github.com/carolinewuyan"},{default:n(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),i(o,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const k=s(m,[["render",d]]);export{T as __pageData,k as default};
